#!/usr/bin/env bash
# Runs inside the aura3d-playwright image on Azure ACR Tasks.
# Executes the requested Playwright specs, then pushes tests/reports/** and
# test-results/** to the Azure Blob container behind $AURA3D_ARTIFACTS_SAS
# (container-level SAS generated by run.sh). Always exits with the
# Playwright exit code so `az acr run` reports test truth.
#
# Env consumed:
#   AURA3D_SPECS_CSV       comma-separated spec paths (required); commas are
#                          used because `az acr run --set` splits on spaces
#   AURA3D_SPECS           space-separated alternative (local/debug use)
#   AURA3D_RUN_ID          run stamp used as the blob prefix (required)
#   AURA3D_REPORTER        --reporter value, default "line"
#   AURA3D_ARTIFACTS_SAS   container SAS URL for artifact upload (optional)
set -uo pipefail

cd /repo

AURA3D_SPECS="${AURA3D_SPECS:-${AURA3D_SPECS_CSV//,/ }}"
: "${AURA3D_SPECS:?AURA3D_SPECS or AURA3D_SPECS_CSV must list the spec files to run}"
: "${AURA3D_RUN_ID:?AURA3D_RUN_ID must stamp this run}"
REPORTER="${AURA3D_REPORTER:-line}"

# `az acr run` does not interpolate secrets into env (verified empirically);
# the SAS arrives base64-encoded via the secret volume at /run/secrets/sas.
if [ -z "${AURA3D_ARTIFACTS_SAS:-}" ] && [ -f /run/secrets/sas ]; then
  AURA3D_ARTIFACTS_SAS="$(base64 -d /run/secrets/sas 2>/dev/null || cat /run/secrets/sas)"
  export AURA3D_ARTIFACTS_SAS
fi

echo "[task-run] run_id=${AURA3D_RUN_ID}"
echo "[task-run] node=$(node --version) pnpm=$(pnpm --version)"
echo "[task-run] specs=${AURA3D_SPECS} reporter=${REPORTER}"

mkdir -p tests/reports test-results

set +e
# shellcheck disable=SC2086 # AURA3D_SPECS intentionally splits on spaces.
pnpm exec playwright test ${AURA3D_SPECS} --reporter="${REPORTER}" 2>&1 | tee /tmp/playwright-output.txt
PW_EXIT=${PIPESTATUS[0]}
set -e

echo "[task-run] PLAYWRIGHT_EXIT=${PW_EXIT}"

# Dump failure evidence into the run log — error-context snapshots carry the
# DOM state (lab status/error text) and do not depend on blob egress.
for ctx in test-results/*/error-context.md; do
  [ -f "$ctx" ] || continue
  echo "[task-run] ===== ${ctx} ====="
  cat "$ctx"
done
if [ -f tests/reports/remote-acr-report.json ]; then
  echo "[task-run] ===== tests/reports/remote-acr-report.json ====="
  cat tests/reports/remote-acr-report.json
fi

# Always attempt artifact egress — failure evidence matters most on red runs.
if [ -n "${AURA3D_ARTIFACTS_SAS:-}" ]; then
  echo "[task-run] uploading artifacts to blob prefix ${AURA3D_RUN_ID}/"
  node tools/remote-acr/upload-artifacts.mjs \
    --sas "${AURA3D_ARTIFACTS_SAS}" \
    --prefix "${AURA3D_RUN_ID}" \
    --copy /tmp/playwright-output.txt playwright-output.txt \
    tests/reports test-results || echo "[task-run] WARNING: artifact upload failed (see messages above)"
else
  echo "[task-run] AURA3D_ARTIFACTS_SAS unset; skipping artifact upload"
fi

# Small on-run manifest so the blob prefix is self-describing.
if [ -n "${AURA3D_ARTIFACTS_SAS:-}" ]; then
  printf '{"runId":"%s","specs":"%s","reporter":"%s","playwrightExit":%s,"finishedUtc":"%s"}\n' \
    "${AURA3D_RUN_ID}" "${AURA3D_SPECS}" "${REPORTER}" "${PW_EXIT}" "$(date -u +%Y-%m-%dT%H:%M:%SZ)" \
    > /tmp/run-manifest.json
  node tools/remote-acr/upload-artifacts.mjs \
    --sas "${AURA3D_ARTIFACTS_SAS}" \
    --prefix "${AURA3D_RUN_ID}" \
    --copy /tmp/run-manifest.json run-manifest.json || true
fi

exit "${PW_EXIT}"
